effect.shader:
#define PI 3.14159265359
vec2 rotate(vec2 v, float angle) {
float s = sin(angle);
float c = cos(angle);
return vec2(v.x * c - v.y * s, v.x * s + v.y * c);
}
vec2 applyWrap(vec2 uv, int mode) {
if (mode == 1) return fract(uv);
if (mode == 2) return abs(mod(uv - 1.0, 2.0) - 1.0);
return uv;
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
vec2 p = uv - center;
p.x *= aspect.x;
float rad = lensRotate * (PI / 180.0);
p = rotate(p, rad);
p.x /= max(0.01, lensRelWidth);
p.y /= max(0.01, lensRelHeight);
float d = length(p);
float edgeSize = lensRadius * lensEdgeWidth;
float magFactor = 1.0;
if (d < lensRadius) {
magFactor = magnifyAmount;
}
else if (d < lensRadius + edgeSize) {
float t = (d - lensRadius) / edgeSize;
float curve = mix(t, smoothstep(0.0, 1.0, t), lensEdgeShape);
magFactor = mix(magnifyAmount, 1.0, curve);
}
vec2 warpedP = p;
warpedP /= (magFactor * magnifyRel);
warpedP.x *= lensRelWidth;
warpedP.y *= lensRelHeight;
warpedP = rotate(warpedP, -rad);
warpedP.x /= aspect.x;
vec2 finalUV = center + warpedP;
finalUV = applyWrap(finalUV, int(wrapMode));
vec4 color = texture2DCv(inputImg.texture, finalUV);
if (d > lensRadius && d < lensRadius + edgeSize) {
color.rgb *= mix(0.95, 1.0, (d - lensRadius) / edgeSize);
}
vec4 base = texture2DCv(inputImg.texture, suv);
gl_FragColor = mix(base, color, blend);
}
